-- =====================================================================
-- 0038 — Atas das reuniões de marketing (32 reuniões, 686 itens)
-- Fonte: Google Docs "Reunião de Planejamento de Marketing - 2026" (texto completo).
-- Cria as tabelas reunioes e reuniao_itens e importa o histórico.
-- Leitura: todos os usuários autenticados. Escrita: liderança.
-- Pode rodar mais de uma vez: SUBSTITUI os itens das reuniões importadas
-- (datas abaixo) pelos do documento. Reuniões criadas no sistema não são afetadas.
-- =====================================================================

create table if not exists reunioes (
  id uuid primary key default gen_random_uuid(),
  data date not null unique,
  estado text not null default 'realizada'
    check (estado in ('realizada', 'em_andamento')),
  presencas jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now()
);

create table if not exists reuniao_itens (
  id uuid primary key default gen_random_uuid(),
  reuniao_id uuid not null references reunioes(id) on delete cascade,
  secao text not null default 'ata' check (secao in ('ata', 'pauta')),
  ordem int not null default 1,
  titulo text not null,
  serie text not null,                 -- título normalizado: liga o mesmo assunto entre reuniões
  detalhamento text,
  plano_acao text,
  prioridade smallint check (prioridade between 1 and 5),
  responsavel_id uuid references profiles(id) on delete set null,
  responsaveis_texto text,             -- nomes citados na ata (inclui quem não tem usuário)
  link text,
  prazo timestamptz,
  status text check (status in ('nao_iniciado', 'em_andamento', 'concluido', 'cancelado')),
  created_at timestamptz not null default now(),
  unique (reuniao_id, secao, ordem)
);
create index if not exists reuniao_itens_serie_idx on reuniao_itens (serie);
create index if not exists reuniao_itens_resp_idx on reuniao_itens (responsavel_id);
create index if not exists reuniao_itens_prazo_idx on reuniao_itens (prazo);

alter table reunioes enable row level security;
alter table reuniao_itens enable row level security;

drop policy if exists "reunioes_select" on reunioes;
create policy "reunioes_select" on reunioes for select using (auth.uid() is not null);
drop policy if exists "reunioes_write" on reunioes;
create policy "reunioes_write" on reunioes for all
  using (public.eh_lideranca()) with check (public.eh_lideranca());

drop policy if exists "reuniao_itens_select" on reuniao_itens;
create policy "reuniao_itens_select" on reuniao_itens for select using (auth.uid() is not null);
drop policy if exists "reuniao_itens_write" on reuniao_itens;
create policy "reuniao_itens_write" on reuniao_itens for all
  using (public.eh_lideranca()) with check (public.eh_lideranca());

