-- Reuniões importadas: substitui os itens (o documento é a fonte).
delete from reuniao_itens
where reuniao_id in (select id from reunioes where data in ('2026-01-05', '2026-01-12', '2026-01-19', '2026-01-26', '2026-02-02', '2026-02-09', '2026-03-02', '2026-03-09', '2026-03-23', '2026-04-02', '2026-04-13', '2026-05-04', '2026-05-11', '2026-05-18', '2026-05-25', '2026-06-01', '2026-06-08', '2026-06-15', '2026-06-22', '2026-06-30', '2026-07-06', '2026-07-13', '2026-07-20', '2026-07-27', '2026-08-03', '2026-08-10', '2026-08-17', '2026-08-24', '2026-08-31', '2026-09-08', '2026-09-14', '2026-10-05'));

insert into reunioes (data, estado, presencas)
select (r->>'data')::date, r->>'estado', coalesce(r->'presencas', '[]'::jsonb)
from tmp_atas, jsonb_array_elements(dados) r
on conflict (data) do update
  set estado = excluded.estado, presencas = excluded.presencas;

insert into reuniao_itens
  (reuniao_id, secao, ordem, titulo, serie, detalhamento, plano_acao, prioridade,
   responsavel_id, responsaveis_texto, link, prazo, status)
select
  ru.id, i->>'secao', (i->>'ordem')::int, i->>'titulo', i->>'serie',
  i->>'detalhamento', i->>'plano', nullif(i->>'prioridade', '')::smallint,
  coalesce(
    (select p.id from profiles p
      where lower(p.email) = case (i->'resp'->>0)
        when 'T' then 'thiago.leal@litoralverde.com.br'
        when 'J' then 'social.media@litoralverde.com.br'
        when 'S' then 'criacao@litoralverde.com.br'
        when 'G' then 'gustavo.monken@litoralverde.com.br'
        else null end
      limit 1),
    (select p.id from profiles p
      where p.nome ilike case (i->'resp'->>0)
        when 'T' then 'Thiago Leal%'
        when 'J' then 'J_ssica Esteves%'
        when 'G' then 'Gustavo Monken%'
        when 'S' then 'Shayene Rempto%'
        when 'C' then 'Cesar Ricart%'
        when 'P' then 'Stephanie%'
        else null end
      limit 1)
  ),
  i->>'resp_texto', i->>'link', nullif(i->>'prazo', '')::timestamptz, i->>'status'
from tmp_atas,
     jsonb_array_elements(dados) r
     join reunioes ru on ru.data = (r->>'data')::date
     cross join lateral jsonb_array_elements(r->'itens') i
on conflict (reuniao_id, secao, ordem) do nothing;

drop table if exists tmp_atas;
